// Records a sanitized failure classification and stops. No automatic replay:
// the gateway owns bounded retries, and replaying blindly could duplicate notifications.
const x = $input.first().json;
const text = String(x.execution?.error?.message || x.trigger?.error?.message || '');
// Phase 4 canonical codes plus Phase 5 failure categories.
const signals = ['CONFIGURATION_ERROR','AUTHENTICATION_ERROR','AUTHORIZATION_ERROR','RATE_LIMITED','ALVERON_SERVER_ERROR','NETWORK_ERROR','INVALID_RESPONSE','VALIDATION_FAILED','LEDGER_ERROR','AUTHENTICATION_FAILED','ALVERON_API_FAILURE','CONFIG_INVALID','CUSTOMER_EMAIL_MISSING','NOTIFICATION_NOT_SENT','DELIVERY_RECONCILIATION_REQUIRED','LEDGER_FAILURE','GATEWAY_AUTHENTICATION_FAILED'];
const transient = ['RATE_LIMITED','ALVERON_SERVER_ERROR','NETWORK_ERROR'];
const matched = signals.filter(s => text.includes(s));
return [{ json: { workflow: x.workflow?.name ?? 'unknown', failingNode: x.execution?.lastNodeExecuted ?? 'unknown', matchedSignals: matched, transient: matched.some(s => transient.includes(s)), manualInterventionRequired: true, automaticReplay: false } }];
